// settings page: sticky section nav beside the form, a pill on phones
<div style={{ display: "grid", gridTemplateColumns: "200px 1fr", gap: 32 }}>
  <ScrollProgress
    sections={[
      { id: "profile", label: "Profile", icon: "user" },
      { id: "notifications", label: "Notifications", icon: "bell" },
      { id: "security", label: "Security", icon: "lock" },
    ]}
    offset={72}
    indicator="none"
    labels={{ title: "Settings sections" }}
    onActiveChange={(id) => history.replaceState(null, "", "#" + id)}
    style={{ position: "sticky", top: 88, alignSelf: "start" }}
  />
  <form>
    <section id="profile"><h2>Profile</h2>…</section>
    <section id="notifications"><h2>Notifications</h2>…</section>
    <section id="security"><h2>Security</h2>…</section>
  </form>
</div>
